//! `cargo xtask theme`: turn `assets/design/theme.json` into the egui design tokens
//! (`crates/spectrum-app/src/tokens.rs`).
//!
//! The generated file holds only values; `theme.rs` is hand-written and consumes them. `ci`
//! regenerates and compares, so the app's tokens cannot drift from the design document unnoticed.

use serde_json::Value;

/// `#rrggbb` or `#rrggbb@NN` (NN = percent opacity) → egui construction.
fn color_expr(hex: &str) -> Option<String> {
    let (base, pct) = match hex.split_once('@') {
        Some((base, pct)) => (base, Some(pct)),
        None => (hex, None),
    };
    let base = base.trim_start_matches('#');
    if base.len() != 6 {
        return None;
    }
    let r = u8::from_str_radix(base.get(0..2)?, 16).ok()?;
    let g = u8::from_str_radix(base.get(2..4)?, 16).ok()?;
    let b = u8::from_str_radix(base.get(4..6)?, 16).ok()?;
    Some(match pct {
        Some(p) => {
            let alpha = p.parse::<f64>().unwrap_or(100.0) / 100.0;
            format!(
                "Color32::from_rgba_unmultiplied_const({r}, {g}, {b}, {})",
                (alpha * 255.0).round() as u8
            )
        }
        None => format!("Color32::from_rgb({r}, {g}, {b})"),
    })
}

fn ident(role: &str) -> String {
    role.to_ascii_uppercase()
}

fn number(v: Option<&Value>) -> Option<f64> {
    v.and_then(Value::as_f64)
}

fn fmt(v: f64) -> String {
    if v == v.trunc() {
        format!("{:.1}", v)
    } else {
        format!("{v}")
    }
}

fn group(theme: &Value, name: &str, kind: GroupKind) -> Option<String> {
    let map = theme.get(name)?.as_object()?;
    let mut out = String::new();
    for (key, value) in map.iter() {
        match kind {
            GroupKind::Const if key.ends_with("_weight") => {
                let n = number(Some(value))?;
                out.push_str(&format!("pub const {}: u16 = {};\n", ident(key), n as u16));
            }
            GroupKind::Const => {
                let n = number(Some(value))?;
                out.push_str(&format!("pub const {}: f32 = {};\n", ident(key), fmt(n)));
            }
            GroupKind::Color => {
                let expr = color_expr(value.as_str()?)?;
                out.push_str(&format!("pub const {}: Color32 = {expr};\n", ident(key)));
            }
        }
    }
    Some(out)
}

#[derive(Clone, Copy)]
enum GroupKind {
    Const,
    Color,
}

pub fn generate(theme: &Value) -> String {
    let mut out = String::new();
    out.push_str(
        "//! Generated by `cargo xtask theme` from assets/design/theme.json. Do not edit.\n",
    );
    out.push_str(
        "//! Values only: `theme.rs` turns them into `egui::Visuals` and `egui::Style`.\n\n",
    );
    out.push_str("use egui::Color32;\n\n");

    if let Some(body) = group(theme, "color", GroupKind::Color) {
        out.push_str("pub mod color {\n    use super::Color32;\n\n");
        out.push_str(&body.indent_with("    "));
        out.push_str("}\n\n");
    }
    for (name, module) in [
        ("radius", "radius"),
        ("size", "size"),
        ("space", "space"),
        ("type", "text"),
    ] {
        if let Some(body) = group(theme, name, GroupKind::Const) {
            out.push_str(&format!("pub mod {module} {{\n"));
            out.push_str(&body.indent_with("    "));
            out.push_str("}\n\n");
        }
    }

    let font = theme
        .get("font")
        .and_then(|f| f.get("family"))
        .and_then(Value::as_str)
        .unwrap_or("Inter");
    let duration = theme
        .get("motion")
        .and_then(|m| m.get("duration_ms"))
        .and_then(Value::as_f64)
        .unwrap_or(220.0);
    out.push_str(&format!("pub const FONT_FAMILY: &str = \"{font}\";\n"));
    out.push_str(&format!(
        "pub const TRANSITION_MS: f32 = {};\n",
        fmt(duration)
    ));
    out
}

trait Indent {
    fn indent_with(&self, prefix: &str) -> String;
}

impl Indent for String {
    fn indent_with(&self, prefix: &str) -> String {
        self.lines()
            .map(|line| format!("{prefix}{line}\n"))
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_and_alpha_become_egui_constructors() {
        assert_eq!(
            color_expr("#ffffff").unwrap_or_default(),
            "Color32::from_rgb(255, 255, 255)"
        );
        assert_eq!(
            color_expr("#0b6fe0").unwrap_or_default(),
            "Color32::from_rgb(11, 111, 224)"
        );
        assert_eq!(
            color_expr("#ffffff@60").unwrap_or_default(),
            "Color32::from_rgba_unmultiplied_const(255, 255, 255, 153)"
        );
        assert!(color_expr("nope").is_none());
    }

    #[test]
    fn whole_numbers_keep_one_decimal() {
        assert_eq!(fmt(52.0), "52.0");
        assert_eq!(fmt(12.5), "12.5");
    }

    #[test]
    fn a_theme_generates_every_group() {
        let theme = serde_json::json!({
            "font": {"family": "Inter"},
            "color": {"window": "#ffffff", "scrim": "#ffffff@60"},
            "radius": {"control": 6},
            "size": {"titlebar_height": 52},
            "space": {"row_inline": 8},
            "type": {"title_size": 15, "title_weight": 600},
            "motion": {"duration_ms": 220},
        });
        let out = generate(&theme);
        assert!(out.contains("pub const WINDOW: Color32 = Color32::from_rgb(255, 255, 255);"));
        assert!(out.contains(
            "pub const SCRIM: Color32 = Color32::from_rgba_unmultiplied_const(255, 255, 255, 153);"
        ));
        assert!(out.contains("pub const CONTROL: f32 = 6.0;"));
        assert!(out.contains("pub const TITLEBAR_HEIGHT: f32 = 52.0;"));
        assert!(out.contains("pub const TITLE_SIZE: f32 = 15.0;"));
        assert!(out.contains("pub const TITLE_WEIGHT: u16 = 600;"));
        assert!(out.contains("pub const FONT_FAMILY: &str = \"Inter\";"));
    }
}
